(() => {
"use strict";
const U=window.DW_UI,V=window.DW_VIEWS,{esc,icon,btn,iconBtn,pill,field,check,notice,table,section,search,progress,square,shell,targetScene}=U;
V.state=s=>{
 const perm=s.variant==='permission';
 return shell(s,'<main class="page state-page"><div class="state-card"><div class="alert-icon '+(perm?'red':"")+'">'+icon(perm?'lock':'file',27)+'</div><h2>'+ (perm?'无法打开工作空间':'此工作空间需要较新版本')+'</h2><p>'+ (perm?'当前目录不可写。已有内容保持原样，请选择有权限的目录或恢复访问后重试。':'当前版本可以读取部分内容，但不能安全写回新的格式。')+'</p><div class="panel" style="margin:24px 0">'+table(['项目','内容'],perm?[['工作空间','个人自动化'],['位置','文档 / 自动化'],['问题','目录没有写入权限']]:[['工作空间','财务工作台'],['工作空间格式','2.0'],['当前可写格式','1.0']])+'</div><div class="row">'+btn(perm?'返回':'检查更新',perm?'recent':'update-available')+btn(perm?'重新选择目录':'只读打开',perm?'native-folder':'workspace-readonly','primary')+'</div></div></main>',{active:'workspace'});
};
V.native=s=>'<div class="native-desktop"><div class="native-dialog"><div class="native-title">'+icon('folder',16)+'选择文件夹<span class="spacer"></span>×</div><div class="native-toolbar">'+icon('back',16)+'　'+icon('refresh',16)+'<span class="native-address">此电脑　›　文档</span><span class="native-find">在“文档”中搜索</span></div><div class="native-content"><aside><span>快速访问</span><b>文档</b><span>下载</span><span>桌面</span><span>此电脑</span></aside><main><div class="native-columns"><span>名称</span><span>修改日期</span><span>类型</span></div>'+[['个人自动化','今天 09:30'],['工作资料','昨天 15:22'],['Exports','10月27日 11:10']].map(([t,d],i)=>'<div class="native-file '+(i===0?'selected':"")+'"><span>'+icon('folder',17)+' '+t+'</span><span>'+d+'</span><span>文件夹</span></div>').join("")+'</main></div><div class="native-bottom"><label>文件夹：<input aria-label="文件夹" value="个人自动化"></label><div class="row">'+btn('取消',s.parent||'recent')+btn('选择此文件夹',s.parent||'create-workspace','primary')+'</div></div></div></div>';
function checklist(items){return'<div class="maintenance-checks">'+items.map(([t,d,state])=>'<div class="maintenance-step"><span class="step-symbol '+state+'">'+icon(state==='done'?'check':state==='fail'?'alert':state==='active'?'refresh':'clock',18)+'</span><div><strong>'+t+'</strong><p>'+d+'</p></div>'+pill(state==='done'?'已完成':state==='active'?'处理中':state==='fail'?'失败':'等待',state==='done'?'green':state==='fail'?'red':state==='active'?'blue':"")+'</div>').join("")+'</div>'}
V.maintenance=s=>{
 let title,desc,steps,tail;
 switch(s.variant){
 case 'backup':title='正在校验备份';desc='个人自动化 · 保存到所选备份目录';steps=[['数据库一致快照','已固定引用集合','done'],['复制流程与资产','18 个对象已复制','done'],['校验长度与摘要','正在校验第 12 / 18 个对象','active'],['完成备份登记','校验成功后登记','wait']];tail=notice('工作空间文档保持可用','备份不会恢复运行或重新发送输入。');break;
 case 'update':title='正在准备更新';desc='DeskWeaveStudio 0.1.0 → 0.2.0';steps=[['保存草稿','2 份打开的文档已保存','done'],['停止活动运行','正在等待子调用与输入释放','active'],['创建一致备份','运行收拢后开始','wait'],['切换组件','核验制品后执行','wait']];tail=btn('查看活动运行','run-stopping','','play');break;
 case 'migration':title='正在升级数据格式';desc='个人自动化 · 原始备份已保留';steps=[['检查独占访问','其他连接已退出维护写入','done'],['创建恢复来源','一致备份已校验','done'],['转换与验证对象','正在核对引用与可编辑性','active'],['打开工作空间','验证成功后开放写入','wait']];tail=notice('升级后保留原始备份','完成验证后再打开流程。');break;
 case 'rollback':title='选择恢复方案';desc='程序版本与数据格式分别恢复';steps=[['程序组件','上一有效版本可用','done'],['当前数据','升级后新增 2 份草稿','done'],['兼容检查','上一版本无法写入当前格式','fail']];tail='<div class="stack">'+notice('保留升级后的内容','将备份恢复到新目录，当前草稿继续保留可导出。','amber')+'<div class="row">'+btn('导出当前内容','package-export')+btn('恢复到新目录','backup-restore','primary','history')+'</div></div>';break;
 default:title='更新未完成';desc='旧版本入口仍然可用';steps=[['下载更新','制品已下载并核验','done'],['准备工作空间','草稿和备份已保存','done'],['组件切换','目标文件被占用，安装未完成','fail']];tail='<div class="stack">'+notice('关闭占用程序后重试','个人工作空间与备份已保留。','amber')+'<div class="row">'+btn('查看恢复方案','rollback')+btn('重试更新','update-preparing','primary','refresh')+'</div></div>';
 }
 return U.titlebar("维护")+ '<div class="app-body"><main class="maintenance-page"><div class="maintenance-card"><div class="maintenance-logo">'+icon(s.variant==='backup'?'database':s.variant==='rollback'?'history':'refresh',30)+'</div><h2>'+title+'</h2><p class="maintenance-desc">'+desc+'</p>'+checklist(steps)+'<div style="margin:23px 0">'+(s.variant==='backup'?progress(68):s.variant==='migration'?progress(58):"")+'</div>'+tail+'</div></main></div>';
};
V.install=s=>{
 const v=s.variant,failed=v==='failed',uninstall=v==='uninstall',progressing=v==='progress';
 const content=progressing?'<h2>正在安装 DeskWeaveStudio</h2><p class="install-lead">安装完成后可直接打开工作台。</p>'+checklist([['桌面应用','程序资源已复制','done'],['执行与控制组件','正在配置本地组件','active'],['WebView2 运行环境','随离线资源检查','wait'],['快捷方式','完成后创建','wait']])+progress(57):failed?'<div class="alert-icon red">'+icon('alert',24)+'</div><h2>安装未完成</h2><p class="install-lead">WebView2 离线资源校验失败，当前安装尚未完成。</p>'+notice('需要重新选择完整安装包','已保留工作空间数据；可以返回安装选项或退出。','red')+'<div class="info-grid" style="margin-top:24px"><div class="info-item">失败组件<strong>WebView2 运行环境</strong></div><div class="info-item">恢复动作<strong>重新取得完整安装包</strong></div></div>':uninstall?'<h2>卸载 DeskWeaveStudio</h2><p class="install-lead">请选择需要移除的内容。</p><div class="stack">'+check('卸载程序组件',true,'桌面应用、执行服务、控制组件与快捷方式')+check('保留工作空间与备份',true,'个人自动化 · 财务工作台')+'<div class="divider"></div><h3>需要单独删除的数据</h3>'+check('文档 / 个人自动化',false,'12 个流程，28 份资产')+check('备份 / 个人自动化',false,'3 份一致备份')+notice('当前选择仅卸载程序','未勾选的数据目录将保留。')+'</div>':'<h2>安装 DeskWeaveStudio</h2><p class="install-lead">为当前用户安装桌面工作台与本地运行组件。</p><div class="stack">'+field('安装位置','个人应用目录 / DeskWeaveStudio')+'<div class="panel"><div class="panel-head">包含组件</div><div class="panel-body stack">'+check('桌面工作台',true)+check('流程执行与桌面控制',true)+check('MCP 本地集成桥',true)+check('离线 WebView2 资源',true)+'</div></div>'+check('创建桌面快捷方式',true)+'</div>';
 return '<div class="installer-backdrop"><div class="installer-window"><div class="native-title">'+icon('flow',16)+'DeskWeaveStudio '+(uninstall?'卸载':'安装')+'<span class="spacer"></span>×</div><div class="installer-body"><aside><span class="brand-mark">D</span><h2>DeskWeaveStudio</h2><p>织序工作台</p><div class="installer-steps"><span class="active">1　安装选项</span><span>2　安装组件</span><span>3　完成</span></div></aside><main>'+content+'</main></div><div class="installer-footer"><span class="muted">'+(uninstall?'程序与用户数据分别处理':'每用户安装')+'</span><span class="spacer"></span>'+btn('退出','recent')+(progressing?'<button class="btn primary" type="button" disabled>正在安装…</button>':btn(failed?'返回安装选项':uninstall?'仅卸载程序':'开始安装',failed?'installer':uninstall?'recent':'install-progress','primary'))+'</div></div></div>';
};
V.about=s=>{
 const notices=s.variant==='notices';
 return shell(s,'<main class="page">'+section(notices?'第三方许可':'关于 DeskWeaveStudio',notices?'组件声明与许可文件':'织序工作台')+(notices?'<div class="panel">'+table(['组件','随发行包提供的文件',''],[['React','LICENSE',btn('查看许可','','small','file')],['Tauri','许可与版权声明',btn('查看许可','','small','file')],['React Flow','LICENSE',btn('查看许可','','small','file')],['Monaco Editor','ThirdPartyNotices.txt',btn('查看声明','','small','file')],['Python 与原生依赖','依赖许可清单',btn('查看清单','','small','file')]])+'</div>':'<div class="about-card"><span class="brand-mark">D</span><h2>DeskWeaveStudio</h2><p class="muted">版本 0.1.0 · Windows x64</p><div class="row" style="margin-top:26px">'+btn('检查更新','update-available','primary','refresh')+btn('使用指南','help-docs','','help')+'</div><div class="divider"></div><div class="about-links">'+btn('第三方许可','thirdparty-notices','ghost','file')+btn('诊断与支持','settings-diagnostics','ghost','shield')+'</div></div>')+'</main>',{active:'settings'});
};
V.help=s=>shell(s,'<main class="page">'+section('帮助与使用指南','按当前任务找到操作步骤',btn('快捷键','shortcuts-help','','keyboard'))+search('搜索使用指南')+'<div class="help-grid">'+[['flow','制作第一条流程','从动作、参数和出口开始组织步骤。','editor-graph'],['record','录制桌面操作','选择目标、录制、裁剪并保存轨迹。','record-config'],['target','模板与定位','采集模板，核对匹配结果与候选。','match-test'],['play','运行与接管','启动、暂停、停止和全局急停。','run-running'],['database','备份与恢复','将一致备份恢复到独立新目录。','backup-restore'],['connect','客户端接入','管理 MCP 的工作空间与目标授权。','settings-mcp']].map(([ic,t,d,to])=>'<button type="button" class="help-card" data-go="'+to+'">'+square(ic)+'<h3>'+t+'</h3><p>'+d+'</p><span>查看操作　→</span></button>').join("")+'</div><div class="panel"><div class="panel-head">常见处理</div><div class="panel-body action-list">'+[['目标窗口关闭了，如何继续？','target-lost'],['保存失败后如何保留草稿？','storage-error'],['急停后如何重新使用桌面？','emergency']].map(([t,to])=>'<button class="command-row" type="button" data-go="'+to+'">'+t+'<span class="spacer"></span>'+icon('chevron',14)+'</button>').join("")+'</div></div></main>');
V.tray=s=>'<div class="desktop-surface tray-desktop">'+targetScene("full")+'<div class="tray-menu"><div class="tray-heading"><span class="brand-mark" style="width:23px;height:23px;font-size:15px">D</span><strong>DeskWeaveStudio</strong></div><div class="tray-running">'+pill('后台运行中','blue')+'<strong>月度报表下载</strong><small>报表中心 · 版本 12</small></div>'+[['grid','打开工作台','workspace'],['play','查看运行','run-running'],['pause','暂停当前运行','run-pausing'],['stop','全局急停','emergency'],['settings','设置','settings-general'],['close','退出','close-unsaved']].map(([ic,t,to])=>'<button type="button" class="command-row" data-go="'+to+'">'+icon(ic,16)+t+'</button>').join("")+'</div><div class="desktop-taskbar"><span>'+icon('grid',20)+'</span><span>'+icon('folder',20)+'</span><span class="spacer"></span><span style="color:#1d4ed8">'+icon('flow',18)+'</span><span>09:42　　2026/10/29</span></div></div>';
})();
